static struct sbp_session * sbp_session_create ( struct sbp_tpg * tpg , u64 guid ) { struct sbp_session * sess ; int ret ; char guid_str [ 17 ] ; snprintf ( guid_str , sizeof ( guid_str ) , "%016llx" , guid ) ; sess = kmalloc ( sizeof ( * sess ) , GFP_KERNEL ) ; spin_lock_init ( & sess -> lock ) ; INIT_LIST_HEAD ( & sess -> login_list ) ; INIT_DELAYED_WORK ( & sess -> maint_work , session_maintenance_work ) ; sess -> guid = guid ; sess -> se_sess = target_setup_session ( & tpg -> se_tpg , 128 , sizeof ( sbp_target_request ) , TARGET_PROT_NORMAL , guid_str , sess , NULL ) ; if ( IS_ERR ( sess -> se_sess ) ) { pr_err ( "failed to init se_session\n" ) ; ret = PTR_ERR ( sess -> se_sess ) ; kfree ( sess ) ; return ERR_PTR ( ret ) ; } return sess ; } 